WITH valid AS (SELECT id, customer_id, device, browser, started_at, country, UPPER(country) AS country_upper, DATE_TRUNC('WEEK', started_at) AS started_at_period FROM sessions WHERE country IS NOT NULL), gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS new_group_flag FROM valid), sessions_sessions AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT CASE WHEN new_group_flag >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END AS new_group_flag_tier, SUM(CASE WHEN browser = 'Chrome' THEN new_group_flag ELSE 0 END) AS chrome_new_group_flag, ROUND(AVG(new_group_flag), 2) AS avg_new_group_flag, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min FROM sessions_sessions GROUP BY CASE WHEN new_group_flag >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END;
